"use strict";(self.webpackChunkrithmia=self.webpackChunkrithmia||[]).push([["3723"],{9426(e,i,a){a.r(i),a.d(i,{metadata:()=>n,default:()=>c,frontMatter:()=>r,contentTitle:()=>o,toc:()=>l,assets:()=>h});var n=JSON.parse('{"id":"Setting/Rithmia/Continents/Glaushun/wavecrest","title":"Wavecrest","description":"Government:","source":"@site/docs/Setting/Rithmia/Continents/Glaushun/wavecrest.md","sourceDirName":"Setting/Rithmia/Continents/Glaushun","slug":"/Setting/Rithmia/Continents/Glaushun/wavecrest","permalink":"/Rithmia/docs/Setting/Rithmia/Continents/Glaushun/wavecrest","draft":false,"unlisted":false,"editUrl":"https://github.com/TravisH18/Rithmia/tree/main/docs/docs/Setting/Rithmia/Continents/Glaushun/wavecrest.md","tags":[],"version":"current","frontMatter":{},"sidebar":"settingSidebar","previous":{"title":"Vaeturnum","permalink":"/Rithmia/docs/Setting/Rithmia/Continents/Glaushun/vaeturnum"},"next":{"title":"Witherwaste (Empire of the Ghouls)","permalink":"/Rithmia/docs/Setting/Rithmia/Continents/Glaushun/witherwaste"}}'),t=a(4848),s=a(8453);let r={},o="Wavecrest",h={},l=[{value:"Government:",id:"government",level:2},{value:"Houses",id:"houses",level:2},{value:"House Reefglow:",id:"house-reefglow",level:3},{value:"House Waverider:",id:"house-waverider",level:3},{value:"House Moonshade:",id:"house-moonshade",level:3},{value:"House Deepgaze:",id:"house-deepgaze",level:3},{value:"House Silverfin:",id:"house-silverfin",level:3},{value:"House Blackscale:",id:"house-blackscale",level:3},{value:"High Regent Sylvaris Windrider",id:"high-regent-sylvaris-windrider",level:3},{value:"Roleplaying Hooks:",id:"roleplaying-hooks",level:3},{value:"Grand Defender, Dormunoz head of judicial system.",id:"grand-defender-dormunoz-head-of-judicial-system",level:3},{value:"Cities",id:"cities",level:2},{value:"Shadowtide Consortium",id:"shadowtide-consortium",level:2},{value:"Notable members:",id:"notable-members",level:3},{value:"Leader: Princess Ellastari Waverider, (The Whispering Siren)",id:"leader-princess-ellastari-waverider-the-whispering-siren",level:3},{value:"Sahuagin",id:"sahuagin",level:2},{value:"Adventure Module",id:"adventure-module",level:2}];function d(e){let i={a:"a",br:"br",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(i.header,{children:(0,t.jsx)(i.h1,{id:"wavecrest",children:"Wavecrest"})}),"\n",(0,t.jsx)(i.h2,{id:"government",children:"Government:"}),"\n",(0,t.jsx)(i.p,{children:"House System: In this unique system, power is divided among powerful noble houses, with each house representing a distinct lineage or bloodline. The aristocratic houses possess hereditary titles and privileges and wield significant influence over the nation's affairs. The houses may have their own internal hierarchies, traditions, and rivalries, with their heads forming a council or assembly that makes collective decisions for the country."}),"\n",(0,t.jsx)(i.h2,{id:"houses",children:"Houses"}),"\n",(0,t.jsx)(i.h3,{id:"house-reefglow",children:"House Reefglow:"}),"\n",(0,t.jsx)(i.p,{children:"Purpose: House Reefglow is known for its mastery of diplomacy and maritime trade. They excel in establishing and maintaining profitable alliances with other underwater kingdoms and surface-dwelling nations. They control vast trading networks and prioritize economic prosperity."}),"\n",(0,t.jsx)(i.p,{children:"Alliances: House Reefglow has strong alliances with the surface-dwelling merchant guilds, underwater trading consortiums, and influential coastal city-states."}),"\n",(0,t.jsx)(i.p,{children:"Rivalries: They have an ongoing rivalry with House Waverider, as both houses vie for control over key trade routes and seek to outdo each other in terms of commercial success and influence."}),"\n",(0,t.jsx)(i.p,{children:"Standing: House Reefglow is highly regarded among the sea elf nation for its economic prowess and diplomatic skills. They hold a prominent position within the government, often contributing financial resources to the nation's endeavors."}),"\n",(0,t.jsx)(i.h3,{id:"house-waverider",children:"House Waverider:"}),"\n",(0,t.jsx)(i.p,{children:"Purpose: House Waverider boasts a formidable naval force and exceptional maritime warfare capabilities. They focus on protecting the sea elf nation's territories, defending against external threats, and expanding their influence through naval conquest."}),"\n",(0,t.jsx)(i.p,{children:"Alliances: House Waverider has forged alliances with powerful merfolk kingdoms and sea creature companions, such as hippocampi and giant turtles, which bolster their naval strength."}),"\n",(0,t.jsx)(i.p,{children:"Rivalries: House Waverider harbors a longstanding rivalry with House Reefglow, viewing their emphasis on commerce as a potential threat to the nation's security and military dominance."}),"\n",(0,t.jsx)(i.p,{children:"Standing: House Waverider holds considerable influence within the government due to its military might. The sea elf people greatly respect them for their dedication to safeguarding their homeland."}),"\n",(0,t.jsx)(i.h3,{id:"house-moonshade",children:"House Moonshade:"}),"\n",(0,t.jsx)(i.p,{children:"Purpose: House Moonshade specializes in arcane arts, ancient lore, and mystic rituals. They are the keepers of ancient magical knowledge and act as advisors to the ruling monarch. They harness their magical abilities to ensure the prosperity and protection of the sea elf kingdom."}),"\n",(0,t.jsx)(i.p,{children:"Alliances: House Moonshade has close ties with elemental beings, particularly water elementals and selkies, who lend their magical aid and guidance."}),"\n",(0,t.jsx)(i.p,{children:"Rivalries: They have a tense relationship with House Deepgaze, as both houses compete for influence in matters of arcane research and interpretation of ancient prophecies."}),"\n",(0,t.jsx)(i.p,{children:"Standing: House Moonshade enjoys a respected position within the government due to their profound magical expertise. They are revered among the sea elf populace as guardians of wisdom and arcane tradition."}),"\n",(0,t.jsx)(i.h3,{id:"house-deepgaze",children:"House Deepgaze:"}),"\n",(0,t.jsx)(i.p,{children:"Purpose: House Deepgaze is renowned for their expertise in exploration, underwater reconnaissance, and knowledge of hidden underwater realms. They undertake daring expeditions, charting new territories, and delving into the depths to uncover ancient relics and lost civilizations."}),"\n",(0,t.jsx)(i.p,{children:"Alliances: House Deepgaze maintains alliances with powerful aquatic creatures, such as giant octopuses and merrow, who assist them in their exploration endeavors."}),"\n",(0,t.jsx)(i.p,{children:"Rivalries: They have a rivalry with House Moonshade, as both houses vie for dominance in matters of exploration and unlocking the secrets of the deep."}),"\n",(0,t.jsx)(i.p,{children:"Standing: House Deepgaze is highly respected for their intrepid spirit and vast knowledge of uncharted territories. The sea elf people look to them for guidance and rely on their discoveries to expand the nation's influence."}),"\n",(0,t.jsx)(i.h3,{id:"house-silverfin",children:"House Silverfin:"}),"\n",(0,t.jsx)(i.p,{children:"Purpose: House Silverfin is dedicated to the preservation and protection of the sea elf nation's natural resources, including marine life, coral reefs, and underwater ecosystems. They are fierce advocates for environmental conservation and sustainable practices."}),"\n",(0,t.jsx)(i.p,{children:"Alliances: House Silverfin forms alliances with druids and sea spirits, working together to maintain the delicate balance of the underwater realm."}),"\n",(0,t.jsx)(i.p,{children:"Rivalries: They often clash with House Blackscale, whose industrial practices and expansionist tendencies are seen as threats to the environment."}),"\n",(0,t.jsx)(i.p,{children:"Standing: House Silverfin is respected among the sea elf population for their commitment to the preservation of their homeland's natural beauty. They have an influential voice in the government, advocating for policies that prioritize ecological well-being."}),"\n",(0,t.jsx)(i.h3,{id:"house-blackscale",children:"House Blackscale:"}),"\n",(0,t.jsx)(i.p,{children:"Purpose: House Blackscale is known for their focus on industry, technology, and expansion. They prioritize economic growth, resource extraction, and territorial expansion to strengthen the sea elf nation's power and influence."}),"\n",(0,t.jsx)(i.p,{children:"Alliances: House Blackscale forms alliances with powerful underwater creatures such as sahuagin or kuo-toa, who share their vision of expansion and offer military support for their endeavors."}),"\n",(0,t.jsx)(i.p,{children:"Rivalries: They have a rivalry with House Silverfin, as the environmental preservation advocated by House Silverfin is seen by House Blackscale as an obstacle to their industrial progress and economic ambitions."}),"\n",(0,t.jsx)(i.p,{children:"Standing: House Blackscale holds a significant position within the government due to their economic influence and the resources they bring to the sea elf nation. While they may face criticism from environmentalists, they have a substantial following among the sea elf populace who believe in their vision of growth and prosperity."}),"\n",(0,t.jsx)(i.p,{children:"House Blackscale's industrial practices and expansionist tendencies can bring about economic benefits and technological advancements for the sea elf nation. However, their pursuit of progress often comes at the cost of the environment and can create conflicts with other houses that prioritize preservation and sustainability. Their standing within the government reflects their economic power and the support they garner from those who seek wealth and progress."}),"\n",(0,t.jsx)(i.h3,{id:"high-regent-sylvaris-windrider",children:"High Regent Sylvaris Windrider"}),"\n",(0,t.jsx)(i.p,{children:"Description: High Regent Sylvaris Windrider is an imposing figure, standing tall with an air of regal authority. With flowing silver hair that seems to shimmer like moonlight, piercing azure eyes, and a graceful demeanor, Sylvaris embodies the elegance and power of the sea elf nobility. Their skin carries a subtle iridescent sheen, reflecting the colors of the ocean depths."}),"\n",(0,t.jsx)(i.p,{children:"Attire: Sylvaris is often adorned in intricately crafted armor, embellished with symbols representing each of the six houses. A majestic cloak of woven kelp and seashells drapes over their shoulders, signifying their role as the unifying figurehead of the sea elf nation. They carry a staff made from a rare and exotic coral, topped with a crystal orb that seems to radiate a soft, soothing light."}),"\n",(0,t.jsx)(i.p,{children:"Personality: Sylvaris possesses a keen intellect, diplomatic finesse, and a sense of duty towards their people. They are known for their impartiality and ability to navigate the intricate webs of intrigue among the noble houses. Sylvaris strives to strike a delicate balance between the interests of the houses, ensuring unity, harmony, and the well-being of the sea elf nation as a whole."}),"\n",(0,t.jsx)(i.p,{children:"Role: As the High Regent, Sylvaris serves as the central authority and the voice of the six houses. They preside over the Council of Houses, where decisions of national importance are deliberated. Sylvaris acts as a mediator, arbitrator, and advisor, guiding the nation through times of peace, war, and political challenges."}),"\n",(0,t.jsx)(i.p,{children:"Backstory: Sylvaris comes from a long lineage of sea elf nobility, tracing their ancestry back to the founding of the sea elf nation. They were chosen as the High Regent due to their exceptional diplomatic skills, strategic acumen, and their ability to bridge the diverse interests of the noble houses. Sylvaris has a deep respect for the traditions, wisdom, and values of the sea elf people."}),"\n",(0,t.jsx)(i.h3,{id:"roleplaying-hooks",children:"Roleplaying Hooks:"}),"\n",(0,t.jsx)(i.p,{children:"Diplomatic Enigma: Sylvaris enjoys engaging in intricate diplomatic maneuvers, and they may seek the assistance of the party in delicate negotiations or resolving disputes among the houses."}),"\n",(0,t.jsx)(i.p,{children:"Guardian of Unity: Sylvaris views the unity of the six houses as crucial for the survival and prosperity of the sea elf nation. They may assign the party missions to strengthen alliances, uncover threats to unity, or safeguard the nation's interests."}),"\n",(0,t.jsx)(i.p,{children:"Seeker of Balance: Sylvaris values maintaining the delicate balance between progress and preservation. They may task the party with quests that involve navigating environmental concerns, political conflicts, or ethical dilemmas."}),"\n",(0,t.jsx)(i.p,{children:"Custodian of Secrets: As a figurehead of the sea elf nation, Sylvaris is privy to ancient lore and hidden knowledge. They may share cryptic hints, send the party on quests to uncover lost artifacts, or reveal the truth behind mysterious events."}),"\n",(0,t.jsx)(i.p,{children:"High Regent Sylvaris Windrider serves as the embodiment of the unity, wisdom, and authority of the six houses. Their guidance and leadership are instrumental in maintaining the stability and prosperity of the sea elf nation, and their interactions with the party can shape the course of the nation's future."}),"\n",(0,t.jsx)(i.h3,{id:"grand-defender-dormunoz-head-of-judicial-system",children:"Grand Defender, Dormunoz head of judicial system."}),"\n",(0,t.jsx)(i.p,{children:"Dormunoz, Guardian of Time is an ancient bronze dragon who has become the head of justice, and patron of Wavecrest as a whole."}),"\n",(0,t.jsx)(i.p,{children:(0,t.jsx)(i.a,{href:"https://genrebomb.com/underwater-campaign-guide-dnd-5e/",children:"https://genrebomb.com/underwater-campaign-guide-dnd-5e/"})}),"\n",(0,t.jsx)(i.p,{children:(0,t.jsx)(i.a,{href:"https://www.skullsplitterdice.com/blogs/dnd/dm-s-guide-to-running-aquatic-and-seafaring-campaigns-for-dnd",children:"https://www.skullsplitterdice.com/blogs/dnd/dm-s-guide-to-running-aquatic-and-seafaring-campaigns-for-dnd"})}),"\n",(0,t.jsx)(i.h2,{id:"cities",children:"Cities"}),"\n",(0,t.jsxs)(i.p,{children:["Pearldale ",(0,t.jsx)(i.em,{children:"Capitol City"})]}),"\n",(0,t.jsx)(i.p,{children:"Tidewatch"}),"\n",(0,t.jsx)(i.p,{children:"Azurelorn"}),"\n",(0,t.jsx)(i.p,{children:"Coralhelm"}),"\n",(0,t.jsx)(i.p,{children:"Each city has a treasury in their main government building that is a chunk of Dormunoz's hoard."}),"\n",(0,t.jsx)(i.p,{children:"Roll for ancient dragon hoard and divide it up into four but remember the sahuagin have captured one part of this hoard from Coral Helm"}),"\n",(0,t.jsx)(i.h2,{id:"shadowtide-consortium",children:"Shadowtide Consortium"}),"\n",(0,t.jsx)(i.p,{children:"The Shadowtide Consortium is a clandestine faction operating within the sea elf government. They possess hidden influence and work against the ideals of the sea elves, driven by their own selfish ambitions. Here's how they maintain secrecy and wield power:"}),"\n",(0,t.jsx)(i.p,{children:"Infiltration and Manipulation: The Shadowtide Consortium consists of skilled infiltrators and manipulators who have managed to secure key positions within the sea elf government. They hold influential roles as advisors, council members, or even trusted advisors to the ruling elite. By carefully concealing their true motives, they can discreetly steer decisions in their favor."}),"\n",(0,t.jsx)(i.p,{children:"Veiled Identities: The members of the Shadowtide Consortium operate under veiled identities, masking their true intentions and allegiances. They may employ aliases, false backgrounds, or magical disguises to hide their involvement with the faction. This allows them to operate freely while remaining undetected by those who might oppose them."}),"\n",(0,t.jsx)(i.p,{children:"Extortion and Blackmail: The Shadowtide Consortium maintains its power by gathering compromising information on influential individuals within the sea elf society. They exploit this knowledge to blackmail and manipulate key figures, ensuring their loyalty and cooperation. Through this leverage, they can suppress dissent and maintain control over critical aspects of the government."}),"\n",(0,t.jsx)(i.p,{children:"Cultivating Internal Divisions: The Shadowtide Consortium capitalizes on existing divisions and rivalries within the sea elf society. They exploit these divisions to sow discord and dissent among the ruling elite and general populace. By fueling internal conflicts, they divert attention away from their own activities and maintain a fragmented society that is easier to manipulate."}),"\n",(0,t.jsx)(i.p,{children:"Occult Knowledge and Magic: The Shadowtide Consortium possesses esoteric knowledge and arcane power, granting them an advantage over those who oppose them. They may have access to ancient and forbidden rituals, allowing them to perform hidden ceremonies or enchantments that further their goals while remaining undetected by magical means."}),"\n",(0,t.jsx)(i.p,{children:"The pursuit of the Key of Stars serves as a catalyst for their hidden activities, as they believe the sahuagin possess it. They work in secret to obtain the artifact, using their influence within the sea elf government to gather resources, enact policies that further their cause, and ensure the artifact's safe retrieval, all while keeping their true intentions concealed from the righteous sea elves who seek to protect their people and ideals."}),"\n",(0,t.jsx)(i.p,{children:"This mysterious faction adds an element of intrigue and political complexity to your campaign, offering opportunities for betrayal, investigation, and challenging moral choices for your players."}),"\n",(0,t.jsx)(i.h3,{id:"notable-members",children:"Notable members:"}),"\n",(0,t.jsx)(i.p,{children:"Seraphine Virel:"}),"\n",(0,t.jsx)(i.p,{children:"Role: Master Manipulator and Information Broker"}),"\n",(0,t.jsx)(i.p,{children:"Description: Seraphine Virel is an elegant and enigmatic sea elf who exudes an air of charisma and intrigue. With flowing silver hair and piercing emerald eyes, she possesses a captivating presence. Seraphine is skilled at acquiring and leveraging information, making her an invaluable asset to The Shadowtide Consortium."}),"\n",(0,t.jsx)(i.p,{children:"Background: Seraphine hails from a noble sea elf family, known for their political influence. She was drawn to The Shadowtide Consortium due to her hunger for power and her desire to shape events behind the scenes. Seraphine is highly intelligent, well-versed in diplomacy, and an expert at manipulating others to further the faction's goals."}),"\n",(0,t.jsx)(i.p,{children:"Roleplaying Hooks:"}),"\n",(0,t.jsx)(i.p,{children:"Seraphine is always seen at exclusive social gatherings and political events, where she discreetly collects valuable information from influential figures."}),"\n",(0,t.jsx)(i.p,{children:"She maintains a network of informants and spies who feed her critical intelligence, ensuring that The Shadowtide Consortium remains a step ahead of their adversaries."}),"\n",(0,t.jsx)(i.p,{children:"Seraphine can offer the player characters vital information or resources in exchange for performing clandestine tasks on behalf of The Shadowtide Consortium."}),"\n",(0,t.jsx)(i.p,{children:"Kaldor Greymoor:"}),"\n",(0,t.jsx)(i.p,{children:"Role: Stealthy Infiltrator and Saboteur"}),"\n",(0,t.jsx)(i.p,{children:"Description: Kaldor Greymoor is a sea elf of lithe build, with a dark complexion and sharp features. He moves with the grace of a predator, blending seamlessly into the shadows. Kaldor is an expert in stealth, sabotage, and gathering crucial information covertly, making him a key operative within The Shadowtide Consortium."}),"\n",(0,t.jsx)(i.p,{children:"Background: Kaldor grew up in a coastal village plagued by sahuagin raids, which fueled his resentment and desire for revenge against surface dwellers. He was recruited by The Shadowtide Consortium, who manipulated his anger and thirst for justice to serve their own hidden agenda. Kaldor now uses his skills to gather intelligence and carry out covert operations."}),"\n",(0,t.jsx)(i.p,{children:"Roleplaying Hooks:"}),"\n",(0,t.jsx)(i.p,{children:"Kaldor excels in infiltration, disguise, and subterfuge, making him the go-to operative for delicate and covert missions. He can provide the player characters with equipment, disguises, or assistance in bypassing security measures."}),"\n",(0,t.jsx)(i.p,{children:"His personal vendetta against the sahuagin drives him to uncover any secrets or weaknesses they may possess, aligning his objectives with the faction's current focus on the Key of Stars."}),"\n",(0,t.jsx)(i.p,{children:"Kaldor's troubled past and internal conflict can lead to moments of doubt or hesitation. He may seek redemption or question the faction's methods, potentially becoming an ally to the player characters if they can appeal to his sense of justice."}),"\n",(0,t.jsx)(i.p,{children:"These NPCs can serve as intricate and secretive characters that add depth and complexity to The Shadowtide Consortium. Their motivations, abilities, and connections can create intriguing storylines and opportunities for the player characters to interact with the faction and uncover its secrets."}),"\n",(0,t.jsx)(i.h3,{id:"leader-princess-ellastari-waverider-the-whispering-siren",children:"Leader: Princess Ellastari Waverider, (The Whispering Siren)"}),"\n",(0,t.jsx)(i.p,{children:"Description: Princess Ellastari is a striking sea elf with flowing silver-blue hair that glimmers like moonlight underwater. Her piercing aquamarine eyes radiate both beauty and an air of cunning. Ellastari possesses a regal and commanding presence, always adorned in intricate jewelry and garments that blend seamlessly with the hues of the ocean depths."}),"\n",(0,t.jsx)(i.p,{children:"Background: Ellastari was born into the royal family of the sea elves and was destined to inherit the throne. However, her path took an unexpected turn when she encountered a young bronze dragon named Aurelia during a diplomatic mission. The dragon recognized the potential for darkness within Ellastari and offered her an alternative path\u2014one of power, manipulation, and hidden influence. Intrigued by the prospect, Ellastari embraced the offer, forsaking her heritage and joining The Shadowtide Consortium."}),"\n",(0,t.jsx)(i.p,{children:"Roleplaying Hooks:"}),"\n",(0,t.jsx)(i.p,{children:"Master of Deception: Ellastari excels in the arts of deception, illusion, and infiltration. She can skillfully assume different identities, using her charisma and charm to manipulate others and further the interests of The Shadowtide Consortium. This makes her an elusive and unpredictable adversary for the player characters."}),"\n",(0,t.jsx)(i.p,{children:"Double Agent Dilemma: Ellastari's position as a princess within the sea elf society allows her to gather valuable intelligence while simultaneously serving The Shadowtide Consortium's agenda. This creates a moral dilemma for her as she walks a delicate tightrope, torn between loyalty to her people and her commitment to the faction. The player characters might find themselves entangled in her web of conflicting loyalties and shifting alliances."}),"\n",(0,t.jsx)(i.p,{children:"The Influence of Aurelia: The presence and influence of Aurelia, the bronze dragon, looms over Ellastari's life and decisions. Aurelia may act as a clandestine advisor or mentor to Ellastari, whispering dark secrets and guiding her actions from the shadows. This connection provides an opportunity for the player characters to uncover the truth about Ellastari's motivations and potentially sway her toward a different path."}),"\n",(0,t.jsx)(i.p,{children:"Personal Redemption: Despite her allegiance to The Shadowtide Consortium, Ellastari may carry a glimmer of doubt and a desire for redemption deep within her. The player characters might be able to appeal to her better nature, prompting internal conflict and the potential for a change of heart. Unveiling the truth about the faction's malicious goals or offering her an alternative path could be a catalyst for her transformation."}),"\n",(0,t.jsx)(i.p,{children:"Ellastari's role as the leader of The Shadowtide Consortium adds an intriguing dynamic to the faction. Her lineage, abilities, and connection to the bronze dragon provide depth to her character, allowing for complex interactions and moral dilemmas for the player characters to navigate."}),"\n",(0,t.jsx)(i.h2,{id:"sahuagin",children:"Sahuagin"}),"\n",(0,t.jsx)(i.p,{children:"The Sahuagin are after a mysterious artifact known as the key of stars. They believe this key will release their god Shark god megalodon thing. They belive the sea elves have kept it hidden since the creature was sealed away hundreds of years ago. Sea elves are worried since the Sahuagin have proven they are able to unleash a cataclysmic force known as the Leviathan, a force on natures made of water from the EEP that is summoned to wipe out underwater civilizations, coastal cities and anything in its path. The marid summoned this Leviathan and has promised if they capture the key of stars he will have the power to unleash their shark god upond the world"}),"\n",(0,t.jsx)(i.p,{children:"GIVE THE KEY OF STARS SOME SEA PEOPLE SOUNDING NAME LIKE R'LOTHUA"}),"\n",(0,t.jsx)(i.p,{children:"Sahuagin are being manipulated by a Marid, summoning creatures from the elemental plane of water and passing it off as their raw power. The Marid has promised that this key of stars is amongst"}),"\n",(0,t.jsx)(i.p,{children:'This marid wants to steal as much of the hoard as possible then escape back to the EEP and place themselves on top of the "food chain" of water genie society as they value wealth over all else.'}),"\n",(0,t.jsx)(i.p,{children:"This marid has a right hand man (Also a marid) who is a part of the shadowtide consortium and is feeding them information on sahuagin whereabouts but leaves out full details in order to try to attack weaker strongholds."}),"\n",(0,t.jsx)(i.p,{children:"Most of sahuagin Civilization is in near the south eastern shores of the sea of stars near The Predator Jungle (split into two parts, the eastern serpent gardens and western feral tropics"}),"\n",(0,t.jsx)(i.h2,{id:"adventure-module",children:"Adventure Module"}),"\n",(0,t.jsx)(i.p,{children:"Sea elf vs. Sahuagin Module"}),"\n",(0,t.jsx)(i.p,{children:"Adventure for level 15-16"}),"\n",(0,t.jsx)(i.p,{children:"Sea elf kingdom of Wavecrest was attacked a few months ago. The sharksbane wall, a large wall to protect the elves from large undersea predators and sahuagin was destroyed and the city of Coralhelm was attacked."}),"\n",(0,t.jsx)(i.p,{children:"Sides of the merros war."}),"\n",(0,t.jsx)(i.p,{children:"Aquatic elves"}),"\n",(0,t.jsx)(i.p,{children:"Dormunoz is an ally as well as the tritons\u202F"}),"\n",(0,t.jsx)(i.p,{children:"Plans to open a whirlpool gate to suck in this megalodon and send them to the plane of water"}),"\n",(0,t.jsxs)(i.p,{children:["Capitol ",(0,t.jsx)(i.a,{href:"https://forgottenrealms.fandom.com/wiki/Myth_Nantar",children:"https://forgottenrealms.fandom.com/wiki/Myth_Nantar"}),"\u202F"]}),"\n",(0,t.jsx)(i.p,{children:"Sahuagin"}),"\n",(0,t.jsx)(i.p,{children:"Merfolk and koalinith allies"}),"\n",(0,t.jsx)(i.p,{children:"Released ancient were-megalodon to destroy sea elf cities and has even hit some coastal towns"}),"\n",(0,t.jsx)(i.p,{children:"These two will be fighting each other and investigating the island as it landed in the disputed territory of the war."}),"\n",(0,t.jsx)(i.p,{children:"Also after the island will be the cloud giant baron and a mysterious cult both believing an item named the eye of xxiphu. The cults name will not be known but the growing influence in the region of this rumored lost abberant city. Black panther watcher paladins with amethyst dragon ally could show up to chase whoever steals the item even if it\u2019s our party."}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://forgottenrealms.fandom.com/wiki/Hex_Locus",children:"https://forgottenrealms.fandom.com/wiki/Hex_Locus"}),(0,t.jsx)(i.br,{}),"\n","The sahuagin side has released a great ",(0,t.jsx)(i.em,{children:'"demigod"'})," the megolodon. Which is just a very very large shark from the Plane of Water."]}),"\n",(0,t.jsx)(i.p,{children:"The high mages of Wavecrest believe the can create a whirlpool gate to the plane of water and send that megolodon back home. However the shark must be weakened and have mutiile rods inserted into the shark to pull it into the whirlpool gate."})]})}function c(e={}){let{wrapper:i}={...(0,s.R)(),...e.components};return i?(0,t.jsx)(i,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}},8453(e,i,a){a.d(i,{R:()=>r,x:()=>o});var n=a(6540);let t={},s=n.createContext(t);function r(e){let i=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function o(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:r(e.components),n.createElement(s.Provider,{value:i},e.children)}}}]);